}


/* AOS Fallback & Safety - Ensures content is NEVER invisible */
[data-aos] {
  opacity: 1 !important;
  transform: none !important;
  visibility: visible !important;
}


/*
==========================================================================
ULTRA MASTER DESIGN SYSTEM - MOHAMED SHABAN EL-ATMANI PORTFOLIO
==========================================================================
*/

/* Clean up Blogger Default Chrome */
.feed-links, .blog-feeds, .post-feeds, .status-msg-wrap, .quickedit { /* #blog-pager unhidden */
  display: none !important;
}

/* Strict Dual Language Engine (HTML[dir="rtl"] & body.is-rtl & body[dir="rtl"]) */
.lang-ar { display: none; }
.lang-en { display: inline-block; }
p.lang-en, div.lang-en, section.lang-en, article.lang-en, h1.lang-en, h2.lang-en, h3.lang-en, h4.lang-en {
  display: block;
}

body.is-rtl .lang-en, html[dir="rtl"] .lang-en, body[dir="rtl"] .lang-en {
  display: none !important;
}

body.is-rtl .lang-ar, html[dir="rtl"] .lang-ar, body[dir="rtl"] .lang-ar {
  display: inline-block !important;
}

body.is-rtl p.lang-ar, body.is-rtl div.lang-ar, body.is-rtl section.lang-ar, 
html[dir="rtl"] p.lang-ar, html[dir="rtl"] div.lang-ar, html[dir="rtl"] section.lang-ar,
body.is-rtl h1.lang-ar, body.is-rtl h2.lang-ar, body.is-rtl h3.lang-ar, body.is-rtl h4.lang-ar,
html[dir="rtl"] h1.lang-ar, html[dir="rtl"] h2.lang-ar, html[dir="rtl"] h3.lang-ar, html[dir="rtl"] h4.lang-ar {
  display: block !important;
}

/* RTL Typography & Spacing Fixes */
body.is-rtl, html[dir="rtl"] body {
  font-family: 'Tajawal', 'Cairo', sans-serif !important;
  direction: rtl !important;
  text-align: right !important;
}

body.is-rtl .hero-grid, html[dir="rtl"] .hero-grid,
body.is-rtl .about-grid, html[dir="rtl"] .about-grid,
body.is-rtl .robovai-grid, html[dir="rtl"] .robovai-grid,
body.is-rtl .contact-grid, html[dir="rtl"] .contact-grid {
  direction: rtl;
}

body.is-rtl .nav-container { flex-direction: row; }
body.is-rtl .exp-card-header { flex-direction: row; }
body.is-rtl .exp-card-icon { margin-left: 14px; margin-right: 0; }
body.is-rtl .contact-method { flex-direction: row; }
body.is-rtl .contact-method-icon { margin-left: 14px; margin-right: 0; }
body.is-rtl .btn i { margin-left: 8px; margin-right: 0; }

/* Interactive Background Canvas */
#bg-canvas {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  z-index: -2;
  pointer-events: none;
  opacity: 0.75;
}

/* Glowing Neon Borders & Glassmorphism 2.0 */
.hero-focus-item, .exp-card, .timeline-content, .skill-category, 
.cert-card, .contact-method, .contact-form-wrapper, .case-card {
  position: relative;
  background: rgba(11, 14, 20, 0.65) !important;
  border: 1px solid rgba(0, 229, 255, 0.2) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  border-radius: 18px !important;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.15) !important;
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) !important;
}

.hero-focus-item:hover, .exp-card:hover, .timeline-content:hover, 
.skill-category:hover, .cert-card:hover, .contact-method:hover, .case-card:hover {
  transform: translateY(-6px) scale(1.015) !important;
  border-color: rgba(0, 229, 255, 0.6) !important;
  box-shadow: 0 15px 40px rgba(0, 229, 255, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.3) !important;
}

/* Glowing Pulsing Orbs Background */
body::before, body::after {
  content: '';
  position: fixed;
  border-radius: 50%;
  filter: blur(140px);
  z-index: -3;
  opacity: 0.22;
  animation: pulseGlow 14s infinite alternate ease-in-out;
}
body::before {
  width: 600px;
  height: 600px;
  background: var(--primary);
  top: -150px;
  right: -150px;
}
body::after {
  width: 550px;
  height: 550px;
  background: var(--secondary);
  bottom: -100px;
  left: -100px;
  animation-delay: -7s;
}

@keyframes pulseGlow {
  0% { transform: translate(0, 0) scale(1); opacity: 0.18; }
  50% { transform: translate(-40px, 60px) scale(1.15); opacity: 0.28; }
  100% { transform: translate(60px, -40px) scale(0.95); opacity: 0.2; }
}

/* Primary Button Glow Effect */
.btn-primary {
  background: linear-gradient(135deg, #00E5FF 0%, #7C4DFF 100%) !important;
  color: #000 !important;
  font-weight: 800 !important;
  box-shadow: 0 0 20px rgba(0, 229, 255, 0.4) !important;
  border: none !important;
  transition: all 0.35s ease !important;
}
.btn-primary:hover {
  transform: translateY(-3px) scale(1.05) !important;
  box-shadow: 0 0 35px rgba(0, 229, 255, 0.7), 0 0 15px rgba(124, 77, 255, 0.5) !important;
}

/* Typewriter Cursor Indicator */
.typewriter-text::after {
  content: '|';
  color: var(--primary);
  animation: blinkCursor 0.8s infinite;
  margin-left: 4px;
}
@keyframes blinkCursor {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}


/*
==========================================================================
10X FUTURISTIC ENGINE - MOHAMED SHABAN EL-ATMANI MASTER EDITION
==========================================================================
*/

/* Scroll Progress Bar */
#scroll-progress {
  position: fixed;
  top: 0;
  left: 0;
  height: 3px;
  width: 0%;
  background: linear-gradient(90deg, #00E5FF, #7C4DFF, #E040FB);
  z-index: 10001;
  box-shadow: 0 0 12px #00E5FF;
  transition: width 0.1s ease-out;
}


}

/* Live System Ticker Bar */
.system-status-bar {
  background: rgba(5, 6, 8, 0.9);
  border-bottom: 1px solid rgba(0, 229, 255, 0.12);
  padding: 5px 0;
  font-size: 0.75rem;
