  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  transition: all 0.3s;
}
.sound-toggle-btn:hover {
  background: rgba(0, 229, 255, 0.2);
  border-color: var(--primary);
  transform: scale(1.1);
}

/* Interactive Cyberpunk Terminal Widget */
.terminal-section {
  padding: 60px 0;
}
.terminal-window {
  background: rgba(5, 7, 12, 0.95);
  border: 1px solid rgba(0, 229, 255, 0.3);
  border-radius: 14px;
  overflow: hidden;
