}


/*
==========================================================================
ULTRA VISUAL & ANIMATION ENGINE - MOHAMED SHABAN EL-ATMANI
==========================================================================
*/

/* 1. DISTINCT SECTION BACKGROUNDS */
.hero {
  background: radial-gradient(circle at 50% 20%, rgba(0, 229, 255, 0.12) 0%, transparent 60%),
              radial-gradient(circle at 80% 80%, rgba(124, 77, 255, 0.1) 0%, transparent 50%);
  position: relative;
}

#about {
  background: linear-gradient(135deg, rgba(124, 77, 255, 0.08) 0%, rgba(5, 6, 8, 0.95) 100%);
  border-top: 1px solid rgba(124, 77, 255, 0.15);
  border-bottom: 1px solid rgba(124, 77, 255, 0.15);
}

#capabilities {
  background: radial-gradient(circle at 20% 50%, rgba(0, 229, 255, 0.08) 0%, transparent 50%),
              linear-gradient(180deg, rgba(11, 14, 20, 0.9) 0%, rgba(5, 6, 8, 0.98) 100%);
}

#robovai {
  background: linear-gradient(180deg, rgba(0, 229, 255, 0.09) 0%, rgba(124, 77, 255, 0.09) 50%, rgba(5, 6, 8, 0.95) 100%);
  border-top: 1px solid rgba(0, 229, 255, 0.2);
  border-bottom: 1px solid rgba(124, 77, 255, 0.2);
}

#experience {
  background: radial-gradient(circle at 50% 50%, rgba(124, 77, 255, 0.07) 0%, transparent 70%);
}

#techno-egypt {
  background: linear-gradient(135deg, rgba(224, 64, 251, 0.08) 0%, rgba(11, 14, 20, 0.95) 100%);
  border-top: 1px solid rgba(224, 64, 251, 0.2);
}

#certifications {
  background: radial-gradient(circle at 80% 30%, rgba(255, 215, 0, 0.06) 0%, transparent 60%),
              linear-gradient(180deg, rgba(5, 6, 8, 0.95) 0%, rgba(11, 14, 20, 0.9) 100%);
}

#gallery {
  background: linear-gradient(180deg, rgba(11, 14, 20, 0.95) 0%, rgba(0, 229, 255, 0.05) 100%);
}

#contact {
  background: radial-gradient(circle at 50% 100%, rgba(0, 229, 255, 0.12) 0%, transparent 60%);
}

/* 2. HERO PROFILE IMAGE PULSING AURA */
.hero-image {
  position: relative;
}
.hero-image img {
  position: relative;
  z-index: 2;
  transition: transform 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.hero-image::before {
  content: '';
  position: absolute;
  inset: -15px;
  border-radius: 30px;
  background: linear-gradient(135deg, #00E5FF, #7C4DFF, #E040FB);
  z-index: 1;
  opacity: 0.5;
  filter: blur(20px);
  animation: heroAura 4s infinite alternate ease-in-out;
}
@keyframes heroAura {
  0% { transform: scale(0.96); opacity: 0.4; }
  100% { transform: scale(1.05); opacity: 0.75; }
}
.hero-image:hover img {
  transform: scale(1.03) rotate(0.5deg);
}

/* 3. CARD TOP GRADIENT LINE SHINE */
.exp-card::before, .case-card::before, .skill-category::before, .cert-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--primary), var(--secondary), transparent);
  opacity: 0.6;
  transition: opacity 0.4s;
  border-radius: 18px 18px 0 0;
}
.exp-card:hover::before, .case-card:hover::before, .skill-category:hover::before, .cert-card:hover::before {
  opacity: 1;
}

/* 4. BUTTON METALLIC SHIMMER ANIMATION */
.btn {
  position: relative;
  overflow: hidden;
}
.btn::after {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: linear-gradient(
    60deg,
    transparent 30%,
    rgba(255, 255, 255, 0.25) 50%,
    transparent 70%
  );
  transform: rotate(30deg) translateY(-100%);
  transition: transform 0.8s ease-in-out;
}
.btn:hover::after {
  transform: rotate(30deg) translateY(100%);
}

/* 5. FLOATING BADGE MICRO-FLOAT */
.hero-badge, .about-badge {
  animation: microFloat 3.5s infinite alternate ease-in-out;
}
@keyframes microFloat {
  0% { transform: translateY(0); }
  100% { transform: translateY(-6px); }
}

/* 6. FULLSCREEN INTERACTIVE LIGHTBOX MODAL */
#lightboxModal {
  position: fixed;
  inset: 0;
  background: rgba(5, 6, 8, 0.95);
  backdrop-filter: blur(25px);
  z-index: 200000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
}
#lightboxModal.open {
  opacity: 1;
  pointer-events: auto;
}
#lightboxImg {
  max-width: 90vw;
  max-height: 85vh;
  border-radius: 16px;
  border: 1px solid var(--border);
  box-shadow: 0 20px 60px rgba(0, 229, 255, 0.3);
  transform: scale(0.9);
  transition: transform 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
#lightboxModal.open #lightboxImg {
  transform: scale(1);
}
#lightboxClose {
  position: absolute;
  top: 30px;
  right: 40px;
  font-size: 2rem;
  color: var(--light);
  cursor: pointer;
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s;
}
body.is-rtl #lightboxClose {
  right: auto;
  left: 40px;
}
#lightboxClose:hover {
  background: var(--primary);
  color: #000;
  transform: scale(1.1);
}


/*
==========================================================================
ULTRA SCROLL TRANSITION & SWIPE ANIMATIONS - NATIVE & ULTRA-SMOOTH
==========================================================================
*/

/* Smooth Scroll Animations on Reveal */
.reveal-on-scroll {
  opacity: 0;
  transform: translateY(45px) scale(0.97);
  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
  will-change: opacity, transform;
}

.reveal-on-scroll.is-visible {
  opacity: 1 !important;
  transform: translateY(0) scale(1) !important;
}

/* Staggered Grid Item Transitions */
.grid-3 > *, .grid-2 > *, .exp-grid > *, .gallery-grid > *, .cert-grid > * {
  opacity: 0;
  transform: translateY(35px);
  transition: opacity 0.7s cubic-bezier(0.16, 1, 0.3, 1), transform 0.7s cubic-bezier(0.16, 1, 0.3, 1);
}

.is-visible .grid-3 > *:nth-child(1), .is-visible .exp-grid > *:nth-child(1), .is-visible .cert-grid > *:nth-child(1) { transition-delay: 0.08s; opacity: 1; transform: translateY(0); }
.is-visible .grid-3 > *:nth-child(2), .is-visible .exp-grid > *:nth-child(2), .is-visible .cert-grid > *:nth-child(2) { transition-delay: 0.18s; opacity: 1; transform: translateY(0); }
.is-visible .grid-3 > *:nth-child(3), .is-visible .exp-grid > *:nth-child(3), .is-visible .cert-grid > *:nth-child(3) { transition-delay: 0.28s; opacity: 1; transform: translateY(0); }
.is-visible .grid-3 > *:nth-child(4), .is-visible .exp-grid > *:nth-child(4), .is-visible .cert-grid > *:nth-child(4) { transition-delay: 0.38s; opacity: 1; transform: translateY(0); }
.is-visible .grid-3 > *:nth-child(5), .is-visible .exp-grid > *:nth-child(5), .is-visible .cert-grid > *:nth-child(5) { transition-delay: 0.48s; opacity: 1; transform: translateY(0); }
.is-visible .grid-3 > *:nth-child(6), .is-visible .exp-grid > *:nth-child(6), .is-visible .cert-grid > *:nth-child(6) { transition-delay: 0.58s; opacity: 1; transform: translateY(0); }

/* Remove the old data-aos opacity override so transitions work! */
[data-aos] {
  opacity: 1 !important;
  transform: none !important;
}

/* Tab Swipe Fade Transition */
.case-study-pane {
  animation: paneSwipeIn 0.45s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
@keyframes paneSwipeIn {
  from { opacity: 0; transform: translateX(25px); }
  to { opacity: 1; transform: translateX(0); }
}
body.is-rtl .case-study-pane {
  animation: paneSwipeInRTL 0.45s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
@keyframes paneSwipeInRTL {
  from { opacity: 0; transform: translateX(-25px); }
  to { opacity: 1; transform: translateX(0); }
}


/* Lighthouse CLS & Layout Stability Fixes */
img {
  max-width: 100%;
  height: auto;
  aspect-ratio: attr(width) / attr(height);
}
.hero-image img {
  width: 100%;
  height: auto;
  aspect-ratio: 1 / 1;
  object-fit: cover;
}
main {
  display: block;
}


