/* ==========================================================================
   DUAL LANGUAGE ENGINE (EN ↔ AR)
   Base: English shown, Arabic hidden.
   When body gets class 'is-rtl' OR html gets dir='rtl': flip visibility.
   CRITICAL: Base hide rule must NOT use !important so RTL rules can override.
   ========================================================================== */

/* Default: English visible, Arabic hidden (NO !important here!) */
.lang-ar { display: none; }
.lang-en { display: inline-block; }

p.lang-en, div.lang-en, section.lang-en, article.lang-en,
h1.lang-en, h2.lang-en, h3.lang-en, h4.lang-en, h5.lang-en, h6.lang-en,
li.lang-en, td.lang-en {
  display: block;
}

/* RTL Mode: Hide English, Show Arabic (WITH !important to override base) */
html.is-rtl .lang-en, html[dir="rtl"] .lang-en,
body.is-rtl .lang-en, body[dir="rtl"] .lang-en {
  display: none !important;
}

html.is-rtl .lang-ar, html[dir="rtl"] .lang-ar,
body.is-rtl .lang-ar, body[dir="rtl"] .lang-ar {
  display: inline-block !important;
}

html.is-rtl p.lang-ar, html.is-rtl div.lang-ar, html.is-rtl section.lang-ar, html.is-rtl article.lang-ar,
html.is-rtl h1.lang-ar, html.is-rtl h2.lang-ar, html.is-rtl h3.lang-ar, html.is-rtl h4.lang-ar, html.is-rtl h5.lang-ar, html.is-rtl h6.lang-ar,
html.is-rtl li.lang-ar, html.is-rtl td.lang-ar,
body.is-rtl p.lang-ar, body.is-rtl div.lang-ar, body.is-rtl section.lang-ar, body.is-rtl article.lang-ar,
body.is-rtl h1.lang-ar, body.is-rtl h2.lang-ar, body.is-rtl h3.lang-ar, body.is-rtl h4.lang-ar, body.is-rtl h5.lang-ar, body.is-rtl h6.lang-ar,
body.is-rtl li.lang-ar, body.is-rtl td.lang-ar {
  display: block !important;
}

/* RTL Typography and Direction */
html.is-rtl, html.is-rtl body, body.is-rtl {
  font-family: 'Tajawal', 'Cairo', sans-serif !important;
  direction: rtl !important;
  text-align: right !important;
}

/* RTL spacing overrides */
body.is-rtl .btn i, body.is-rtl .btn svg { margin-left: 8px; margin-right: 0; }
body.is-rtl .nav-links { padding-right: 0; }
body.is-rtl .section-title, body.is-rtl .section-subtitle { text-align: center; }



