div.script:
//
// ============================================================
// MASTER LANGUAGE ENGINE
// ============================================================
window.setLanguage = function(lang) {
  try {
    localStorage.setItem('preferredLanguage', lang);
    document.documentElement.setAttribute('lang', lang);
    document.documentElement.setAttribute('dir', lang === 'ar' ? 'rtl' : 'ltr');

    if (lang === 'ar') {
      document.body.classList.add('is-rtl');
      document.body.classList.remove('is-ltr');
      document.body.setAttribute('dir', 'rtl');
    } else {
      document.body.classList.add('is-ltr');
      document.body.classList.remove('is-rtl');
      document.body.setAttribute('dir', 'ltr');
    }

    var toggleTexts = document.querySelectorAll('.lang-toggle-text');
    for (var i = 0; i < toggleTexts.length; i++) {
      toggleTexts[i].textContent = (lang === 'ar') ? 'EN' : 'AR';
    }
  } catch(e) {
    console.error('Language Toggle Error:', e);
  }
};

window.toggleLanguage = function() {
  var currentLang = localStorage.getItem('preferredLanguage') || 'en';
  var newLang = (currentLang === 'en') ? 'ar' : 'en';
  window.setLanguage(newLang);
};

// Initialize language immediately
(function() {
  var savedLang = localStorage.getItem('preferredLanguage') || 'en';
  window.setLanguage(savedLang);
})();

document.addEventListener('DOMContentLoaded', function() {
  var savedLang = localStorage.getItem('preferredLanguage') || 'en';
  window.setLanguage(savedLang);
  // NOTE: onclick="toggleLanguage()" on the button handles clicks.
  // Do NOT add addEventListener here or it will double-toggle!
});

// ============================================================
// SAFE AOS INITIALIZATION
// ============================================================
window.addEventListener('load', function() {
  if (typeof AOS !== 'undefined') {
    try {
      AOS.init({
        duration: 850,
        easing: 'ease-out-cubic',
        once: true,
        offset: 40
      });
    } catch(e) {}
  }
});

// ============================================================
// SCROLL PROGRESS & NAVBAR
// ============================================================
var lastScrollY = window.scrollY;

window.addEventListener('scroll', function() {
  var winScroll = document.body.scrollTop || document.documentElement.scrollTop;
  var height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
  var scrolled = (winScroll / height) * 100;
  var progress = document.getElementById('scroll-progress');
  if (progress) progress.style.width = scrolled + '%';

  var backBtn = document.getElementById('backToTop');
  if (backBtn) {
    if (winScroll > 400) {
      backBtn.classList.add('show');
    } else {
      backBtn.classList.remove('show');
    }
  }

  var navbar = document.getElementById('navbar');
  if (navbar) {
    // Shrink logic
    if (window.scrollY > 40) {
      navbar.classList.add('scrolled');
    } else {
      navbar.classList.remove('scrolled');
    }

    // Auto-hide logic (Smart Header)
    if (window.scrollY > lastScrollY && window.scrollY > 80) {
      // Scrolling down
      navbar.classList.add('nav-hidden');
    } else {
      // Scrolling up
      navbar.classList.remove('nav-hidden');
    }
    lastScrollY = window.scrollY;
  }
});

window.scrollToTop = function() {
  window.scrollTo({ top: 0, behavior: 'smooth' });
};

// ============================================================
// MOBILE MENU TOGGLE
// ============================================================
document.addEventListener('DOMContentLoaded', function() {
  var mobileToggle = document.getElementById('mobileToggle');
  var navLinks = document.getElementById('navLinks');

  if (mobileToggle && navLinks) {
    mobileToggle.addEventListener('click', function() {
      navLinks.classList.toggle('active');
      mobileToggle.innerHTML = navLinks.classList.contains('active')
        ? '<i class="fas fa-times"></i>'
        : '<i class="fas fa-bars"></i>';
    });
  }
});

// ============================================================
// GALLERY FILTER
// ============================================================
window.filterGallery = function(category) {
  var items = document.querySelectorAll('.gallery-item');
  var buttons = document.querySelectorAll('.tab-btn');

  for (var i = 0; i < buttons.length; i++) {
    buttons[i].classList.remove('active');
    var onclick = buttons[i].getAttribute('onclick') || '';
    if (onclick.indexOf(category) !== -1) {
      buttons[i].classList.add('active');
    }
  }

  for (var j = 0; j < items.length; j++) {
    if (category === 'all' || items[j].getAttribute('data-category') === category) {
      items[j].classList.remove('hidden');
      items[j].style.display = 'block';
    } else {
      items[j].classList.add('hidden');
      items[j].style.display = 'none';
    }
  }
};

// ============================================================
// LIGHTBOX FOR IMAGES
// ============================================================
window.openLightbox = function(src) {
  var modal = document.getElementById('lightboxModal');
  var img = document.getElementById('lightboxImg');
  if (modal && img) {
    img.src = src;
    modal.classList.add('open');
  }
};

window.closeLightbox = function(e) {
  var modal = document.getElementById('lightboxModal');
  if (modal && (e.target.id === 'lightboxModal' || e.target.id === 'lightboxClose' || (e.target.closest && e.target.closest('#lightboxClose')))) {
    modal.classList.remove('open');
  }
};

document.addEventListener('DOMContentLoaded', function() {
  var images = document.querySelectorAll('.gallery-item img, .techno-gallery img, .cert-hero-image img, .experience-media img');
  for (var i = 0; i < images.length; i++) {
    images[i].style.cursor = 'zoom-in';
    (function(img) {
      img.addEventListener('click', function() {
        window.openLightbox(img.src);
      });
    })(images[i]);
  }
});

// ============================================================
// SMOOTH ANCHOR SCROLLING
// ============================================================
document.addEventListener('DOMContentLoaded', function() {
  var anchors = document.querySelectorAll('a[href^="#"]');
  for (var i = 0; i < anchors.length; i++) {
    anchors[i].addEventListener('click', function(e) {
      var targetId = this.getAttribute('href');
      if (!targetId || targetId === '#') return;
      var target = document.querySelector(targetId);
      if (target) {
        e.preventDefault();
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        var navLinks = document.getElementById('navLinks');
        var mobileToggle = document.getElementById('mobileToggle');
        if (navLinks) navLinks.classList.remove('active');
        if (mobileToggle) mobileToggle.innerHTML = '<i class="fas fa-bars"></i>';
      }
    });
  }
});

// ============================================================
// SCROLL REVEAL ANIMATION (IntersectionObserver)
// ============================================================
document.addEventListener('DOMContentLoaded', function() {
  var sections = document.querySelectorAll('section, .hero-grid, .about-grid, .robovai-grid, .contact-grid, .techno-grid, .exp-card, .cert-card, .timeline-item, .skill-category');

  var observer = new IntersectionObserver(function(entries) {
    for (var i = 0; i < entries.length; i++) {
      if (entries[i].isIntersecting) {
        entries[i].target.classList.add('is-visible');
      }
    }
  }, {
    threshold: 0.1,
    rootMargin: '0px 0px -30px 0px'
  });

  for (var j = 0; j < sections.length; j++) {
    sections[j].classList.add('reveal-on-scroll');
    observer.observe(sections[j]);
  }
});

// ============================================================
// EXECUTIVE SHOOTING STARS & METEOR SHOWER CANVAS ENGINE
// ============================================================
window.addEventListener('load', function() {
  var canvas = document.getElementById('bg-canvas');
  if (!canvas) return;
  var ctx = canvas.getContext('2d');

  var w = canvas.width = window.innerWidth;
  var h = canvas.height = window.innerHeight;

  window.addEventListener('resize', function() {
    w = canvas.width = window.innerWidth;
    h = canvas.height = window.innerHeight;
  });

  // Background Twinkling Stars
  var stars = [];
  var starCount = Math.min(Math.floor(w / 12), 90);
  for (var i = 0; i < starCount; i++) {
    stars.push({
      x: Math.random() * w,
      y: Math.random() * h,
      radius: Math.random() * 1.2 + 0.3,
      alpha: Math.random(),
      speed: Math.random() * 0.02 + 0.005
    });
  }

  // Falling Meteors / Shooting Stars
  var meteors = [];
  function createMeteor() {
    return {
      x: Math.random() * w * 1.3 - w * 0.15,
      y: -50,
      length: Math.random() * 80 + 40,
      speed: Math.random() * 6 + 4,
      size: Math.random() * 1.5 + 0.8,
      color: Math.random() > 0.4 ? '#00E5FF' : '#7C4DFF',
      alpha: 1
    };
  }

  for (var m = 0; m < 4; m++) {
    var met = createMeteor();
    met.y = Math.random() * h * 0.7;
    meteors.push(met);
  }

  function draw() {
    ctx.clearRect(0, 0, w, h);

    // 1. Draw Twinkling Stars
    for (var i = 0; i < stars.length; i++) {
      var s = stars[i];
      s.alpha += s.speed;
      if (s.alpha > 1 || s.alpha < 0.1) s.speed = -s.speed;

      ctx.beginPath();
      ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255, 255, 255, ' + Math.abs(s.alpha) * 0.7 + ')';
      ctx.fill();
    }

    // 2. Draw Shooting Stars with glowing trails
    for (var j = 0; j < meteors.length; j++) {
      var meteor = meteors[j];

      meteor.x += meteor.speed * 0.8;
      meteor.y += meteor.speed;

      var gradient = ctx.createLinearGradient(
        meteor.x, meteor.y,
        meteor.x - meteor.length * 0.8, meteor.y - meteor.length
      );
      gradient.addColorStop(0, meteor.color);
      gradient.addColorStop(0.3, 'rgba(0, 229, 255, 0.4)');
      gradient.addColorStop(1, 'transparent');

      ctx.beginPath();
      ctx.moveTo(meteor.x, meteor.y);
      ctx.lineTo(meteor.x - meteor.length * 0.8, meteor.y - meteor.length);
      ctx.strokeStyle = gradient;
      ctx.lineWidth = meteor.size;
      ctx.lineCap = 'round';
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(meteor.x, meteor.y, meteor.size + 0.5, 0, Math.PI * 2);
      ctx.fillStyle = '#FFFFFF';
      ctx.shadowBlur = 10;
      ctx.shadowColor = meteor.color;
      ctx.fill();
      ctx.shadowBlur = 0;

      if (meteor.y > h + 100 || meteor.x > w + 100) {
        meteors[j] = createMeteor();
      }
    }

    if (Math.random() < 0.015 && meteors.length < 8) {
      meteors.push(createMeteor());
    }

    requestAnimationFrame(draw);
  }

  draw();
});


// ============================================================
// NATIVE BLOGGER CONTACT FORM INTEGRATION
// ============================================================
document.addEventListener('DOMContentLoaded', function() {
  var contactForm = document.getElementById('contactForm');
  if (contactForm) {
    contactForm.addEventListener('submit', function(event) {
      event.preventDefault();

      var nameVal = contactForm.querySelector('[name="name"]').value;
      var emailVal = contactForm.querySelector('[name="email"]').value;
      var interestVal = contactForm.querySelector('[name="interest"]').value;
      var messageVal = contactForm.querySelector('[name="message"]').value;

      var nativeName = document.getElementById('ContactForm1_contact-form-name');
      var nativeEmail = document.getElementById('ContactForm1_contact-form-email');
      var nativeMsg = document.getElementById('ContactForm1_contact-form-email-message');
      var nativeSubmit = document.getElementById('ContactForm1_contact-form-button-submit');

      if (nativeName && nativeEmail && nativeMsg && nativeSubmit) {
        nativeName.value = nameVal;
        nativeEmail.value = emailVal;
        nativeMsg.value = "Project Type: " + interestVal + "\n\nMessage: " + messageVal;

        var submitBtn = contactForm.querySelector('button[type="submit"]');
        var originalBtnHtml = submitBtn.innerHTML;
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Sending / جاري الإرسال...';

        nativeSubmit.click();

        var checkInterval = setInterval(function() {
          var nativeSuccess = document.querySelector('#ContactForm1 .contact-form-success-message');
          var nativeError = document.querySelector('#ContactForm1 .contact-form-error-message');

          if (nativeSuccess && nativeSuccess.style.display === 'block') {
            clearInterval(checkInterval);
            submitBtn.innerHTML = '<i class="fas fa-check"></i> Sent / تم الإرسال!';
            submitBtn.style.background = '#00ff88';
            contactForm.reset();
            if (typeof showToast === 'function') showToast('📧 Message Sent Successfully / تم إرسال رسالتك بنجاح!');
            setTimeout(function() {
              submitBtn.disabled = false;
              submitBtn.innerHTML = originalBtnHtml;
              submitBtn.style.background = '';
              nativeSuccess.style.display = 'none';
            }, 3000);
          } else if (nativeError && nativeError.style.display === 'block') {
            clearInterval(checkInterval);
            submitBtn.disabled = false;
            submitBtn.innerHTML = originalBtnHtml;
            if (typeof showToast === 'function') showToast('❌ Send Failed / فشل الإرسال، حاول مجدداً.');
            nativeError.style.display = 'none';
          }
        }, 500);
      } else {
        if (typeof showToast === 'function') showToast('⚠️ Contact widget loading, please retry in 2 seconds.');
      }
    });
  }
});

// ============================================================
// LIVE UTC CLOCK
// ============================================================
function updateClock() {
  var now = new Date();
  var clock = document.getElementById('live-utc-clock');
  if (clock) {
    var hours = String(now.getUTCHours()).padStart(2, '0');
    var mins = String(now.getUTCMinutes()).padStart(2, '0');
    var secs = String(now.getUTCSeconds()).padStart(2, '0');
    clock.textContent = 'UTC ' + hours + ':' + mins + ':' + secs;
  }
}
setInterval(updateClock, 1000);
updateClock();
