body.script:
//
/* ==========================================================================
   PRO BLOGGER ENGINE (TOC, SCROLL PROGRESS, READ TIME, CODE COPY, SHORTCODES)
   ========================================================================== */
document.addEventListener('DOMContentLoaded', function() {
  // 1. Reading Scroll Progress Bar
  var progressBar = document.createElement('div');
  progressBar.id = 'reading-progress-bar';
  document.body.appendChild(progressBar);

  window.addEventListener('scroll', function() {
    var winScroll = document.documentElement.scrollTop || document.body.scrollTop;
    var height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
    var scrolled = (height > 0) ? (winScroll / height) * 100 : 0;
    progressBar.style.width = scrolled + '%';
  });

  // Execute single article enhancements if on post page
  var postBody = document.querySelector('.post-body');
  if (postBody) {
    // 2. Reading Time & Word Count Calculation
    var text = postBody.textContent || postBody.innerText || '';
    var words = text.trim().split(/\s+/).filter(Boolean).length;
    var readingTime = Math.ceil(words / 200);

    var metaContainer = document.querySelector('.post-header, .post-title');
    if (metaContainer) {
      var readMeta = document.createElement('div');
      readMeta.className = 'post-read-meta';
      readMeta.innerHTML = '<span class="lang-en">⏱️ ' + readingTime + ' min read | 📝 ' + words + ' words</span>' +
                           '<span class="lang-ar">⏱️ ' + readingTime + ' دقائق قراءة | 📝 ' + words + ' كلمة</span>';
      metaContainer.parentNode.insertBefore(readMeta, metaContainer.nextSibling);
    }

    // 3. Automatic Collapsible Table of Contents (TOC)
    var headings = postBody.querySelectorAll('h2, h3');
    if (headings.length >= 2) {
      var tocCard = document.createElement('div');
      tocCard.className = 'post-toc-card';

      var tocHeader = document.createElement('div');
      tocHeader.className = 'toc-header';
      tocHeader.innerHTML = '<h4 class="toc-title"><i class="fas fa-list-ul"></i> <span class="lang-en">Table of Contents</span><span class="lang-ar">جدول المحتويات</span></h4>' +
                            '<i class="fas fa-chevron-down toc-toggle-icon"></i>';

      var tocList = document.createElement('ul');
      tocList.className = 'toc-list';

      headings.forEach(function(heading, index) {
        var id = 'toc-heading-' + index;
        heading.id = id;

        var li = document.createElement('li');
        li.className = 'toc-' + heading.tagName.toLowerCase();

        var a = document.createElement('a');
        a.href = '#' + id;
        a.textContent = heading.textContent;
        a.addEventListener('click', function(e) {
          e.preventDefault();
          heading.scrollIntoView({ behavior: 'smooth' });
        });

        li.appendChild(a);
        tocList.appendChild(li);
      });

      tocHeader.addEventListener('click', function() {
        var isHidden = tocList.style.display === 'none';
        tocList.style.display = isHidden ? 'flex' : 'none';
        tocHeader.querySelector('.toc-toggle-icon').style.transform = isHidden ? 'rotate(0deg)' : 'rotate(-90deg)';
      });

      tocCard.appendChild(tocHeader);
      tocCard.appendChild(tocList);
      postBody.insertBefore(tocCard, postBody.firstChild);
    }

    // 4. One-Click Code Copy Button on <pre><code> blocks
    var codeBlocks = postBody.querySelectorAll('pre');
    codeBlocks.forEach(function(pre) {
      var wrapper = document.createElement('div');
      wrapper.className = 'code-wrapper';
      pre.parentNode.insertBefore(wrapper, pre);
      wrapper.appendChild(pre);

      var copyBtn = document.createElement('button');
      copyBtn.className = 'code-copy-btn';
      copyBtn.innerHTML = '<i class="far fa-copy"></i> <span class="lang-en">Copy</span><span class="lang-ar">نسخ</span>';

      copyBtn.addEventListener('click', function() {
        var codeText = pre.textContent;
        navigator.clipboard.writeText(codeText).then(function() {
          copyBtn.innerHTML = '<i class="fas fa-check"></i> <span class="lang-en">Copied!</span><span class="lang-ar">تم النسخ!</span>';
          setTimeout(function() {
            copyBtn.innerHTML = '<i class="far fa-copy"></i> <span class="lang-en">Copy</span><span class="lang-ar">نسخ</span>';
          }, 2000);
        });
      });

      wrapper.appendChild(copyBtn);
    });

    // 5. Author Box Insertion
    var authorBox = document.createElement('div');
    authorBox.className = 'post-author-box';
    authorBox.innerHTML = '<div class="author-avatar-wrapper">' +
      '<img src="https://i.ibb.co/wFn9v7B6/shield-libya.jpg" alt="Mohamed Shaban El-Atmani" referrerpolicy="no-referrer"/>' +
      '</div>' +
      '<div class="author-info-wrapper">' +
      '<h4><span class="lang-en">Mohamed Shaban El-Atmani</span><span class="lang-ar">محمد شعبان العتماني</span></h4>' +
      '<div class="author-role"><span class="lang-en">Applied AI Engineer &amp; Technical Product Builder</span><span class="lang-ar">مهندس ذكاء اصطناعي تطبيقي ومطور منتجات تقنية</span></div>' +
      '<p class="author-bio"><span class="lang-en">Turning complex real-world problems into practical AI-powered products, intelligent software systems, and automation.</span><span class="lang-ar">متخصص في تحويل المشكلات الواقعية المعقدة إلى منتجات برمجية وحلول ذكاء اصطناعي عملية.</span></p>' +
      '</div>';

    postBody.parentNode.insertBefore(authorBox, postBody.nextSibling);
  }
});
//

//

// ============================================================
// LEGENDARY PORTFOLIO INTERACTIVE EXPERIENCE ENGINE
// ============================================================
document.addEventListener('DOMContentLoaded', function() {

  // 1. Setup Custom Cursor
  var cursor = document.createElement('div');
  cursor.id = 'custom-cursor';
  var cursorDot = document.createElement('div');
  cursorDot.id = 'custom-cursor-dot';
  document.body.appendChild(cursor);
  document.body.appendChild(cursorDot);

  document.addEventListener('mousemove', function(e) {
    cursor.style.left = e.clientX + 'px';
    cursor.style.top = e.clientY + 'px';
    cursorDot.style.left = e.clientX + 'px';
    cursorDot.style.top = e.clientY + 'px';
  });

  document.querySelectorAll('a, button, .post-outer, .capability-card').forEach(function(el) {
    el.addEventListener('mouseenter', function() {
      cursor.style.width = '40px';
      cursor.style.height = '40px';
      cursor.style.backgroundColor = 'rgba(56, 189, 248, 0.1)';
      cursor.style.borderColor = '#00d4ff';
    });
    el.addEventListener('mouseleave', function() {
      cursor.style.width = '20px';
      cursor.style.height = '20px';
      cursor.style.backgroundColor = 'transparent';
      cursor.style.borderColor = '#38bdf8';
    });
  });

  // 2. Synthesize High-Tech Click & Hover Sound Effects using Web Audio API
  var audioCtx = new (window.AudioContext || window.webkitAudioContext)();

  function playBeep(freq, type, duration, vol) {
    try {
      if (audioCtx.state === 'suspended') return; // Browser blocks audio until interaction, which is fine.
      var osc = audioCtx.createOscillator();
      var gain = audioCtx.createGain();
      osc.type = type;
      osc.frequency.value = freq;
      gain.gain.setValueAtTime(vol, audioCtx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.00001, audioCtx.currentTime + duration);
      osc.connect(gain);
      gain.connect(audioCtx.destination);
      osc.start();
      osc.stop(audioCtx.currentTime + duration);
    } catch(e) {}
  }

  // Bind audio to buttons and hovers
  document.querySelectorAll('a, button').forEach(function(el) {
    el.addEventListener('mouseenter', function() {
      playBeep(880, 'sine', 0.05, 0.03); // Subtle high pitch tick on hover
    });
    el.addEventListener('click', function() {
      playBeep(440, 'triangle', 0.15, 0.1); // Synth click beep on tap
    });
  });

  // 3. Constellation Particle Background in Hero
  var heroSec = document.querySelector('.hero');
  if (heroSec) {
    var canvas = document.createElement('canvas');
    canvas.id = 'particle-canvas';
    heroSec.insertBefore(canvas, heroSec.firstChild);

    var ctx = canvas.getContext('2d');
    var particles = [];

    function resizeCanvas() {
      canvas.width = heroSec.offsetWidth;
      canvas.height = heroSec.offsetHeight;
    }
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    // Initialize particles
    for (var i = 0; i < 40; i++) {
      particles.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        vx: (Math.random() - 0.5) * 0.5,
        vy: (Math.random() - 0.5) * 0.5,
        r: Math.random() * 2 + 1
      });
    }

    function animateParticles() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'rgba(56, 189, 248, 0.3)';
      ctx.strokeStyle = 'rgba(56, 189, 248, 0.05)';

      particles.forEach(function(p, idx) {
        p.x += p.vx;
        p.y += p.vy;

        if (p.x < 0 || p.x > canvas.width) p.vx *= -1;
        if (p.y < 0 || p.y > canvas.height) p.vy *= -1;

        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fill();

        for (var j = idx + 1; j < particles.length; j++) {
          var p2 = particles[j];
          var dist = Math.hypot(p.x - p2.x, p.y - p2.y);
          if (dist < 100) {
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.stroke();
          }
        }
      });
      requestAnimationFrame(animateParticles);
    }
    animateParticles();
  }





  // 4. Pure JS 3D Card Tilt Effect
  document.querySelectorAll('.post-outer, .capability-card, .related-post-card').forEach(function(card) {
    card.addEventListener('mousemove', function(e) {
      var rect = card.getBoundingClientRect();
      var x = e.clientX - rect.left;
      var y = e.clientY - rect.top;

      var xc = rect.width / 2;
      var yc = rect.height / 2;

      var angleX = (yc - y) / 15;
      var angleY = (x - xc) / 15;

      card.style.transform = 'perspective(1000px) rotateX(' + angleX + 'deg) rotateY(' + angleY + 'deg) translateY(-5px)';
    });

    card.addEventListener('mouseleave', function() {
      card.style.transform = 'perspective(1000px) rotateX(0deg) rotateY(0deg) translateY(0)';
    });
  });

  // Enable audio context on first user click (browser security requirement)
  document.addEventListener('click', function() {
    if (audioCtx.state === 'suspended') {
      audioCtx.resume();
    }
  }, { once: true });
});

