window.addEventListener('load', function() {
  var p = document.getElementById('preloader');
  if (p) { p.classList.add('loaded'); setTimeout(function() { p.style.display = 'none'; }, 700); }
});
//

// ==========================================================================
// APPLE PRO 3D CAMERA SCROLL and TILT ENGINE
// ==========================================================================
(function() {
  'use strict';

  // 1. Reading Progress Bar
  const progressBar = document.createElement('div');
  progressBar.id = 'appleProgressBar';
  document.body.appendChild(progressBar);

  window.addEventListener('scroll', function() {
    const scrollTop = window.scrollY || document.documentElement.scrollTop;
    const docHeight = document.documentElement.scrollHeight - window.innerHeight;
    const progress = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;
    progressBar.style.width = progress + '%';
  }, { passive: true });

  // 2. Wrap Sections with 3D Viewport
  document.querySelectorAll('section, .hero, footer').forEach(function(el) {
    el.classList.add('apple-3d-reveal');
  });

  // 3. 3D Scroll Perspective Observer
  if ('IntersectionObserver' in window) {
    const observerOptions = {
      threshold: 0.1,
      rootMargin: '0px 0px -50px 0px'
    };

    const revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-inview');
        }
      });
    }, observerOptions);

    document.querySelectorAll('.apple-3d-reveal').forEach(function(el) {
      revealObserver.observe(el);
    });
  } else {
    document.querySelectorAll('.apple-3d-reveal').forEach(function(el) {
      el.classList.add('is-inview');
    });
  }

  // 4. Interactive 3D Card Tilt with Dynamic Specular Spotlight
  const tiltCards = document.querySelectorAll('.exp-card, .cert-card, .capability-card, .robovai-skill-card, .timeline-content');

  tiltCards.forEach(function(card) {
    card.classList.add('has-spotlight');

    // Inject spotlight element
    const spotlight = document.createElement('div');
    spotlight.className = 'card-spotlight';
    card.appendChild(spotlight);

    let isHovering = false;

    card.addEventListener('mouseenter', function() {
      isHovering = true;
    });

    card.addEventListener('mousemove', function(e) {
      if (!isHovering) return;
      const rect = card.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const centerX = rect.width / 2;
      const centerY = rect.height / 2;

      // Max tilt angle 7deg for Apple elegance
      const rotateX = ((y - centerY) / centerY) * -7;
      const rotateY = ((x - centerX) / centerX) * 7;

      card.style.transform = 'perspective(1000px) rotateX(' + rotateX.toFixed(2) + 'deg) rotateY(' + rotateY.toFixed(2) + 'deg) translateZ(12px)';
      spotlight.style.background = 'radial-gradient(circle 280px at ' + x + 'px ' + y + 'px, rgba(56, 189, 248, 0.16), transparent 80%)';
    });

    card.addEventListener('mouseleave', function() {
      isHovering = false;
      card.style.transform = 'perspective(1000px) rotateX(0deg) rotateY(0deg) translateZ(0)';
      spotlight.style.background = 'none';
    });
  });

  // 5. Ensure all images have referrerpolicy and lazy loading
  document.querySelectorAll('img').forEach(function(img) {
    if (!img.getAttribute('referrerpolicy')) {
      img.setAttribute('referrerpolicy', 'no-referrer');
    }
  });
})();
